/// <summary>
/// Data contract class for handling the import of DMF data packages
/// </summary>
[DataContract]
class OMGInboundHandlerDataContract_DMFPackage
{
    OMGDMFDefinitionGroup           definitionGroupName;
    OMGOverwriteDMFImportDefinition overwriteDMFImportDefinition;

}

Method.Source:
[DataMember]
public OMGDMFDefinitionGroup parmDefinitionGroupName(OMGDMFDefinitionGroup _definitionGroupName = definitionGroupName)
{
    definitionGroupName = _definitionGroupName;

    return definitionGroupName;
}

[DataMember]
public OMGOverwriteDMFImportDefinition parmOverwriteDMFImportDefinition(OMGOverwriteDMFImportDefinition _overwriteDMFImportDefinition = overwriteDMFImportDefinition)
{
    overwriteDMFImportDefinition = _overwriteDMFImportDefinition;

    return overwriteDMFImportDefinition;
}

/// <summary>
/// Validates the contract values
/// </summary>
/// <returns>True if ok</returns>
public boolean validate()
{
    // Nothing to validate
    return true;
}
